-- Batch 3: Database normalization, PL/pgSQL, Git conventions (from Google Drive bootcamp slides)

insert into public.portfolio_ai_articles (slug, title, description, category_slug, tags, technologies, published_at, updated_at, reading_time, difficulty, author, featured, cover_emoji, body, sort_order) values ('database-normalization-1nf-to-3nf', 'Database Normalization: 1NF to 3NF, With the Anomaly Each Step Fixes', 'Normalization rules are easy to memorize and hard to apply, because nobody tells you which specific bug each normal form actually prevents. Here''s the anomaly behind each step.', 'backend-notes', ARRAY['PostgreSQL', 'SQL', 'Database']::text[], ARRAY['PostgreSQL', 'SQL']::text[], '2026-07-11', null, 8, 'intermediate', 'Hen Heang', false, '🗂️', $json$[{"type":"paragraph","text":"\"Remove partial dependencies\" means nothing until you've seen the bug it prevents. Normalization has four concrete failure modes it's fixing, and once you can name the anomaly, the rule stops being abstract."},{"type":"heading","level":2,"text":"The four anomalies normalization prevents","id":"four-anomalies"},{"type":"table","headers":["Anomaly","What actually happens"],"rows":[["Data redundancy","The same fact (a customer's address) is repeated on every row that references them, wasting space and inviting drift."],["Insertion anomaly","You can't record a fact (a new subject exists) without also fabricating an unrelated fact (a student who takes it)."],["Update anomaly","A value is duplicated across rows; updating it in one row but not the others leaves the table self-contradictory."],["Deletion anomaly","Deleting the last row referencing something (the last student in a subject) accidentally deletes the subject itself."]]},{"type":"heading","level":2,"text":"1NF: no repeating groups, atomic values","id":"1nf"},{"type":"code","language":"sql","filename":"Not 1NF -- repeating group in one cell","code":"-- enrol_id | student_name | subject\n-- 102      | Maria        | C++, Java"},{"type":"code","language":"sql","filename":"1NF -- one subject per row","code":"-- enrol_id | student_name | subject\n-- 102      | Maria        | C++\n-- 102      | Maria        | Java"},{"type":"paragraph","text":"Cramming \"C++, Java\" into one cell means you can never write a clean WHERE subject = 'Java' — you'd have to pattern-match a comma-separated string. One value per cell is the whole rule."},{"type":"heading","level":2,"text":"2NF: remove partial dependencies on a composite key","id":"2nf"},{"type":"paragraph","text":"This only matters when the primary key is composite (more than one column). If student_name depends only on student_id — not on the full (student_id, subject_id) pair — that's a partial dependency, and it's what causes the anomaly."},{"type":"code","language":"sql","filename":"Before -- composite PK (student_id, subject_id)","code":"-- student_id | student_name | subject_id | subject | scores | country_code | country\n-- 101        | Robert       | 1          | Java    | 70     | US           | United States\n-- 102        | Maria        | 1          | Java    | 79     | US           | United States\n-- 102        | Maria        | 2          | C++     | 58     | US           | United States"},{"type":"callout","variant":"warning","text":"student_name, country_code, and country depend only on student_id — not on the composite key. subject depends only on subject_id. Both are partial dependencies, and they're why deleting Alex's one enrollment row loses the fact that Alex exists at all."},{"type":"code","language":"sql","filename":"After -- split into student, subject, student_subject","code":"create table student (\n  student_id int primary key,\n  student_name text,\n  country_code text,\n  country text\n);\n\ncreate table subject (\n  subject_id int primary key,\n  subject text\n);\n\ncreate table student_subject (\n  student_id int references student(student_id),\n  subject_id int references subject(subject_id),\n  scores int,\n  primary key (student_id, subject_id)\n);"},{"type":"heading","level":2,"text":"Why phone numbers and national IDs make bad primary keys","id":"bad-primary-keys"},{"type":"paragraph","text":"A primary key needs to be stable and always available — a phone number can change, and you can't guarantee a national ID format is unique across every country you might onboard a user from. Both are data, not identity. Use a surrogate key (auto-increment integer or UUID) and keep the phone number or national ID as a regular unique-constrained column instead."},{"type":"callout","variant":"best-practice","text":"In most real projects, 3NF is enough to eliminate the anomalies that actually bite you. Sometimes a table gets deliberately denormalized afterward to avoid an expensive join — that's a conscious performance tradeoff, not a normalization mistake."}]$json$::jsonb, 9) on conflict (slug) do nothing;
insert into public.portfolio_ai_articles (slug, title, description, category_slug, tags, technologies, published_at, updated_at, reading_time, difficulty, author, featured, cover_emoji, body, sort_order) values ('plpgsql-control-flow-if-case-loop', 'PL/pgSQL Control Flow: IF, CASE, and LOOP in a DO Block', 'Every PL/pgSQL block starts the same way — DO $$ ... $$ LANGUAGE plpgsql — and everything else is IF, CASE, or LOOP wearing different syntax.', 'backend-notes', ARRAY['PostgreSQL', 'SQL', 'PL/pgSQL']::text[], ARRAY['PostgreSQL']::text[], '2026-07-11', null, 6, 'intermediate', 'Hen Heang', false, '⚙️', $json$[{"type":"paragraph","text":"PL/pgSQL is PostgreSQL's procedural extension to plain SQL — the thing you reach for when a query alone can't express the logic (branching, looping, reusable functions). Every anonymous block has the same shape."},{"type":"code","language":"sql","filename":"The basic shape","code":"DO $$\nDECLARE\n  message VARCHAR := 'hello world';\nBEGIN\n  RAISE NOTICE 'The message is %', message;\nEND;\n$$ LANGUAGE plpgsql;"},{"type":"heading","level":2,"text":"IF / ELSIF / ELSE","id":"if-statement"},{"type":"code","language":"sql","code":"DO $$\nDECLARE\n  a integer := 10;\n  b integer := 10;\nBEGIN\n  IF a > b THEN\n    RAISE NOTICE 'a is greater than b';\n  ELSIF a < b THEN\n    RAISE NOTICE 'a is less than b';\n  ELSE\n    RAISE NOTICE 'a is equal to b';\n  END IF;\nEND $$;"},{"type":"heading","level":2,"text":"CASE: simple vs searched","id":"case-statement"},{"type":"code","language":"sql","filename":"Simple CASE -- matches an exact value","code":"DO $$\nDECLARE x INTEGER := 1;\nBEGIN\n  CASE x\n    WHEN 1, 2 THEN\n      RAISE NOTICE 'one or two';\n    ELSE\n      RAISE NOTICE 'other value than one or two';\n  END CASE;\nEND $$;"},{"type":"code","language":"sql","filename":"Searched CASE -- matches a boolean condition","code":"DO $$\nDECLARE x INTEGER := 8;\nBEGIN\n  CASE\n    WHEN x BETWEEN 0 AND 10 THEN\n      RAISE NOTICE 'value is between zero and ten';\n    WHEN x BETWEEN 11 AND 20 THEN\n      RAISE NOTICE 'value is between eleven and twenty';\n  END CASE;\nEND $$;"},{"type":"callout","variant":"tip","text":"Use simple CASE when you're matching a variable against exact values (like a switch statement). Use searched CASE the moment the condition involves a range, comparison, or anything that isn't equality."},{"type":"heading","level":2,"text":"LOOP with an explicit EXIT","id":"loop-statement"},{"type":"code","language":"sql","code":"DO $$\nDECLARE count INTEGER := 10;\nBEGIN\n  LOOP\n    IF count > 100 THEN\n      EXIT;\n    END IF;\n    RAISE NOTICE 'Count %', count;\n    count := count + 10;\n  END LOOP;\nEND $$;"},{"type":"paragraph","text":"A bare LOOP has no built-in exit condition — you provide one yourself with IF ... THEN EXIT, or the more idiomatic EXIT WHEN condition;. Forgetting it is how you write an infinite loop inside a transaction, which is a much worse debugging session than an infinite loop in application code."}]$json$::jsonb, 10) on conflict (slug) do nothing;
insert into public.portfolio_ai_articles (slug, title, description, category_slug, tags, technologies, published_at, updated_at, reading_time, difficulty, author, featured, cover_emoji, body, sort_order) values ('git-commit-and-branch-naming-conventions', 'Git Commit and Branch Naming Conventions I Actually Follow', 'A branch name and a commit message are read far more often than they''re written. Two small conventions that make a repo''s history skimmable instead of archaeological.', 'career-notes', ARRAY['Git', 'Code Review', 'Conventions']::text[], '{}'::text[], '2026-07-11', null, 5, 'beginner', 'Hen Heang', false, '🌿', $json$[{"type":"paragraph","text":"Without a naming convention, a team's branch list and commit history become confusing to navigate — nobody can tell what a branch is for or what a commit actually changed without opening it. Two small, cheap conventions fix most of that."},{"type":"heading","level":2,"text":"Branch names: start with a group word","id":"branch-naming"},{"type":"list","items":["Regular branches are permanent: dev (changes get reviewed and tested before merging to master) and master (stable, no direct commits, merge only via review).","Temporary branches get created and deleted per unit of work: bug fixes, hotfixes, feature branches.","Prefix with a group word that matches the workflow — bug- for something that needs fixing soon, WIP- for work you know won't finish soon.","Use hyphens or slashes as separators, e.g. bug-logo-alignment-issue.","Some teams prefix with the author's name instead, e.g. chantha_feature_login — useful when several people work the same feature area in parallel."]},{"type":"callout","variant":"warning","text":"Avoid branch names that are only numbers or that run too long to read in a terminal prompt. If you can't tell what a branch is for from its name alone, the name failed its one job."},{"type":"heading","level":2,"text":"Conventional Commits: one prefix, instant scanability","id":"conventional-commits"},{"type":"code","language":"text","code":"<type>: message\n\nfeat: allow provide config object to extend other configs\nstyle: color changed in navbar"},{"type":"paragraph","text":"The type prefix (feat, fix, style, refactor, docs, test, chore...) turns a commit log into something you can scan for exactly the kind of change you're looking for — git log --oneline | grep '^fix' actually works when the team follows this. It also unlocks automated tooling: changelogs and semantic version bumps can be generated directly from commit history because the type is machine-parseable, not just a human hint."},{"type":"callout","variant":"best-practice","text":"The value isn't the convention itself — it's that every commit becomes self-describing without opening the diff. A reviewer scanning fix: null pointer on empty cart before opening the PR already knows more than a bare Update CartService.java ever tells them."}]$json$::jsonb, 11) on conflict (slug) do nothing;

insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('2nf-table-split', '2NF Table Split (Composite Key → Three Tables)', 'sql', 'create table student (
  student_id int primary key,
  student_name text,
  country_code text,
  country text
);

create table subject (
  subject_id int primary key,
  subject text
);

create table student_subject (
  student_id int references student(student_id),
  subject_id int references subject(subject_id),
  scores int,
  primary key (student_id, subject_id)
);', ARRAY['PostgreSQL', 'SQL', 'Database']::text[], 'A composite primary key (student_id, subject_id) with student_name depending only on student_id is a partial dependency — the classic 2NF violation. Splitting into three tables removes it.', 10) on conflict (snippet_id) do nothing;
insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('plpgsql-if-case-loop', 'PL/pgSQL: IF, CASE, and LOOP in One Block', 'sql', 'DO $$
DECLARE
  a INTEGER := 10;
  count INTEGER := 0;
BEGIN
  IF a > 5 THEN
    RAISE NOTICE ''a is greater than five'';
  END IF;

  CASE a
    WHEN 10 THEN RAISE NOTICE ''a is exactly ten'';
    ELSE RAISE NOTICE ''a is something else'';
  END CASE;

  LOOP
    EXIT WHEN count >= 3;
    RAISE NOTICE ''count = %'', count;
    count := count + 1;
  END LOOP;
END $$;', ARRAY['PostgreSQL', 'PL/pgSQL']::text[], 'The three control-flow shapes that cover almost every anonymous PL/pgSQL block: conditional branching, exact-value matching, and a manually-bounded loop.', 11) on conflict (snippet_id) do nothing;
insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('conventional-commit-format', 'Conventional Commit Message Format', 'text', '<type>: <short summary>

feat: add idempotency check to auto-pay endpoint
fix: null pointer on empty cart at checkout
refactor: extract JWT parsing into JwtUtils
docs: add MyBatis dynamic SQL examples to README
chore: bump spring-boot-starter-security to 3.2.1', ARRAY['Git', 'Conventions']::text[], 'One prefix makes a commit self-describing and lets tooling generate changelogs directly from git history instead of someone writing them by hand.', 12) on conflict (snippet_id) do nothing;

insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('identify-normal-form-violation', 'Identify which normal form a table violates', 'database', 'Get a specific diagnosis (1NF/2NF/3NF, and which columns) instead of a generic "normalize your schema" suggestion.', 'Here is a table schema with sample rows: [paste schema + a few rows]. Which normal form does this violate first (1NF, 2NF, or 3NF), and which specific columns cause it? Do not redesign the schema yet — just the diagnosis.', 'A specific normal form violation named, with the exact column(s) causing it — not a full redesigned schema.', ARRAY['Paste real sample rows, not just column names — anomalies are easiest to spot with actual duplicate data visible.', 'Ask for the diagnosis before the fix — understand which rule is broken before restructuring anything.', 'Follow up by asking for the split tables only after you''ve confirmed the diagnosis makes sense to you.']::text[], ARRAY['SQL', 'Database', 'PostgreSQL']::text[], 12) on conflict (prompt_id) do nothing;
;
